#!/usr/bin/env python3
"""Applications of KW witness counting theory — self-contained version."""
from math import comb, log2, sqrt, pi

def fiber_tf(n, k, l):
    return 0 if k == 0 else n * comb(n-1, k-1) * comb(n-1, l)

def fiber_ft(n, k, l):
    return 0 if l == 0 else n * comb(n-1, k) * comb(n-1, l-1)

def fiber_total(n, k, l):
    return fiber_tf(n, k, l) + fiber_ft(n, k, l)

def kw_witness_count_symmetric(n, profile):
    total = 0
    for k in range(n+1):
        if not profile[k]: continue
        for l in range(n+1):
            if profile[l]: continue
            total += fiber_total(n, k, l)
    return total

def kw_witness_count_threshold(n, t):
    return kw_witness_count_symmetric(n, [k >= t for k in range(n+1)])

def boundary_contribution(n, t):
    return comb(n, t) * comb(n, t-1)

def fiber_decomposition(n, profile):
    result = {}
    for k in range(n+1):
        if not profile[k]: continue
        for l in range(n+1):
            if profile[l]: continue
            tf, ft = fiber_tf(n,k,l), fiber_ft(n,k,l)
            result[(k,l)] = {"tf": tf, "ft": ft, "total": tf+ft}
    return result

def witness_entropy(n, profile):
    c = kw_witness_count_symmetric(n, profile)
    return log2(c) if c > 0 else 0.0

if __name__ == "__main__":
    print("=" * 60)
    print("APPLICATIONS OF KW WITNESS COUNTING")
    print("=" * 60)

    print("
1. Communication bounds for majority")
    for n in [5, 10, 15, 20]:
        t = (n+1)//2
        kw = kw_witness_count_threshold(n, t)
        bl = boundary_contribution(n, t)
        print(f"  Maj({n}): |KW|={kw}, entropy={log2(kw):.1f}, boundary_lb={bl}")

    print("
2. KW vs Wasserstein-1")
    for n in [3, 5, 7, 10, 15]:
        t = (n+1)//2
        kw = kw_witness_count_threshold(n, t)
        w1 = sum(comb(n,k)*comb(n,l)*abs(k-l) for k in range(t,n+1) for l in range(t))
        print(f"  n={n}: KW={kw}, W1={w1}, ratio={kw/w1:.4f}")

    print("
3. Fiber heatmap for Thresh(6,3)")
    for (k,l), d in sorted(fiber_decomposition(6, [k>=3 for k in range(7)]).items()):
        print(f"  ({k},{l}): {d}")

